export function makeTable() {
  return { kind: 'table', map: new Map(), headerDefined: false }
}

export function makeArray(isTableArray = false) {
  return { kind: 'array', items: [], isTableArray }
}

export function makeScalar(kind, value) {
  return { kind, value }
}

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}
"}

