{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-I3ZF0R/src/lexer.js","content":"// A small cursor over a single line's text, used by the line-oriented parser.
import { ParseError } from './nodes.js'

export class LineState {
  constructor(text, lineNo) {
    this.text = text
    this.pos = 0
    this.lineNo = lineNo
  }

  fail(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  peek() {
    return this.text[this.pos]
  }

  atCommentOrEnd() {
    const c = this.text[this.pos]
    return this.pos >= this.text.length || c === '#' || c === ';'
  }

  skipWs() {
    while (this.pos < this.text.length && (this.text[this.pos] === ' ' || this.text[this.pos] === '\t')) {
      this.pos++
    }
  }
}

const NAME_CHAR = /[A-Za-z0-9_-]/

// Parses a single (possibly quoted) name segment.
export function parseName(state) {
  state.skipWs()
  const c = state.peek()
  if (c === '"') return parseBasicString(state)
  if (c === "'") return parseLiteralString(state)
  const start = state.pos
  while (state.pos < state.text.length && NAME_CHAR.test(state.text[state.pos])) {
    state.pos++
  }
  if (state.pos === start) state.fail('expected a name')
  return state.text.slice(start, state.pos)
}

// Parses a dotted name into an array of decoded segment strings.
export function parseDottedName(state) {
  const segments = [parseName(state)]
  while (true) {
    state.skipWs()
    if (state.peek() === '.') {
      state.pos++
      state.skipWs()
      segments.push(parseName(state))
    } else {
      break
    }
  }
  return segments
}

const ESCAPES = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', '0': '\0' }

export function parseBasicString(state) {
  const { text, lineNo } = state
  state.pos++ // opening quote
  let out = ''
  while (true) {
    if (state.pos >= text.length) state.fail('unterminated string')
    const c = text[state.pos]
    if (c === '"') {
      state.pos++
      return out
    }
    if (c === '\\') {
      const esc = text[state.pos + 1]
      if (esc === undefined) state.fail('unterminated string')
      if (esc === 'u') {
        const hex = text.slice(state.pos + 2, state.pos + 6)
        if (hex.length !== 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) {
          state.fail('invalid escape \\u')
        }
        out += String.fromCharCode(parseInt(hex, 16))
        state.pos += 6
        continue
      }
      if (Object.prototype.hasOwnProperty.call(ESCAPES, esc)) {
        out += ESCAPES[esc]
        state.pos += 2
        continue
      }
      throw new ParseError(lineNo, `invalid escape \\${esc}`)
    }
    out += c
    state.pos++
  }
}

export function parseLiteralString(state) {
  const { text } = state
  state.pos++ // opening quote
  const start = state.pos
  while (true) {
    if (state.pos >= text.length) state.fail('unterminated string')
    if (text[state.pos] === "'") {
      const out = text.slice(start, state.pos)
      state.pos++
      return out
    }
    state.pos++
  }
}
"}

