{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-I3ZF0R/src/values.js","content":"// Value grammar: booleans, numbers, strings, arrays and inline tables.
import { makeArray, makeScalar, makeTable, ParseError } from './nodes.js'
import { parseBasicString, parseDottedName, parseLiteralString } from './lexer.js'
import { assignDottedKey } from './assign.js'

const INT_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

const TOKEN_DELIMS = new Set([' ', '\t', ',', ']', '}'])

// selfPath: the dotted-name path (array of decoded strings) at which this
// value is being defined; used only so inline tables and their nested values
// can build accurate "key <path> is defined twice" style error paths.
export function parseValue(state, selfPath) {
  state.skipWs()
  if (state.atCommentOrEnd()) state.fail('expected a value')
  const c = state.peek()
  if (c === '"') return makeScalar('string', parseBasicString(state))
  if (c === "'") return makeScalar('string', parseLiteralString(state))
  if (c === '[') return parseArray(state, selfPath)
  if (c === '{') return parseInlineTable(state, selfPath)
  if (c === ',' || c === ']' || c === '}') state.fail('expected a value')

  const start = state.pos
  while (state.pos < state.text.length && !TOKEN_DELIMS.has(state.text[state.pos])) {
    state.pos++
  }
  const token = state.text.slice(start, state.pos)
  if (token === 'true') return makeScalar('boolean', true)
  if (token === 'false') return makeScalar('boolean', false)
  if (INT_RE.test(token)) {
    return makeScalar('integer', Number(token.replace(/_/g, '')))
  }
  if (FLOAT_RE.test(token) && /[.eE]/.test(token)) {
    return makeScalar('float', Number(token.replace(/_/g, '')))
  }
  throw new ParseError(state.lineNo, `invalid value ${token}`)
}

function parseArray(state, selfPath) {
  state.pos++ // '['
  const node = makeArray(false)
  state.skipWs()
  while (true) {
    if (state.atCommentOrEnd()) state.fail('unterminated array')
    if (state.peek() === ']') {
      state.pos++
      return node
    }
    const value = parseValue(state, selfPath)
    node.items.push(value)
    state.skipWs()
    if (state.atCommentOrEnd()) state.fail('unterminated array')
    const c = state.peek()
    if (c === ',') {
      state.pos++
      state.skipWs()
      continue
    }
    if (c === ']') {
      state.pos++
      return node
    }
    state.fail('trailing text after a value')
  }
}

function parseInlineTable(state, selfPath) {
  state.pos++ // '{'
  const node = makeTable()
  state.skipWs()
  if (state.atCommentOrEnd()) state.fail('unterminated inline table')
  if (state.peek() === '}') {
    state.pos++
    return node
  }
  while (true) {
    const segments = parseDottedName(state)
    state.skipWs()
    if (state.atCommentOrEnd()) state.fail('expected = in an inline table')
    if (state.peek() !== '=') state.fail('expected = in an inline table')
    state.pos++
    state.skipWs()
    const childPath = selfPath.concat(segments)
    const value = parseValue(state, childPath)
    assignDottedKey(node, segments, value, selfPath, state.lineNo)
    state.skipWs()
    if (state.atCommentOrEnd()) state.fail('unterminated inline table')
    const c = state.peek()
    if (c === ',') {
      state.pos++
      state.skipWs()
      continue
