// Assigns `value` into `table` at `segments` (a dotted-name path), creating
// intermediate tables as the dots walk through. `prefix` is the path from
// the document root to `table`, used only to build full error paths.
export function assignDottedKey(table, segments, value, prefix, lineNo) {
  let current = table
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i]
    const isLast = i === segments.length - 1
    const pathSoFar = prefix.concat(segments.slice(0, i + 1)).join('.')
    if (isLast) {
      if (current.map.has(seg)) {
        throw new ParseError(lineNo, `key ${pathSoFar} is defined twice`)
      }
      current.map.set(seg, value)
      return
    }
    let child = current.map.get(seg)
    if (child === undefined) {
      child = makeTable()
      current.map.set(seg, child)
    } else if (child.kind === 'table') {
