    const seg = segments[i]
    path.push(seg)
    const isLast = i === segments.length - 1
    let child = current.map.get(seg)
    if (child === undefined) {
      child = makeTable()
      current.map.set(seg, child)
    } else if (child.kind === 'array' && child.isTableArray) {
      child = lastTableOf(child)
    } else if (child.kind !== 'table') {
      throw new ParseError(lineNo, `${path.join('.')} is not a table`)
    }
