// `[[name]]` header.
export function resolveArrayTableHeader(root, segments, lineNo) {
  let current = root
  const path = []
  for (let i = 0; i < segments.length; i++) {
    const seg = segments[i]
    path.push(seg)
    const isLast = i === segments.length - 1
    let child = current.map.get(seg)
    if (!isLast) {
      if (child === undefined) {
        child = makeTable()
        current.map.set(seg, child)
