{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-I3ZF0R/src/format.js","content":"// Renders a parsed document tree as canonical JSON or as a `keys` listing.

function compareCodePoints(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const d = ca[i].codePointAt(0) - cb[i].codePointAt(0)
    if (d !== 0) return d
  }
  return ca.length - cb.length
}

function sortedKeys(table) {
  return [...table.map.keys()].sort(compareCodePoints)
}

function jsonValue(node, indent) {
  switch (node.kind) {
    case 'table': {
      const keys = sortedKeys(node)
      if (keys.length === 0) return '{}'
      const inner = indent + '  '
      const lines = keys.map(
        (k) => inner + JSON.stringify(k) + ': ' + jsonValue(node.map.get(k), inner)
      )
      return '{\n' + lines.join(',\n') + '\n' + indent + '}'
    }
    case 'array': {
      const items = node.items
      if (items.length === 0) return '[]'
      const inner = indent + '  '
      const lines = items.map((it) => inner + jsonValue(it, inner))
      return '[\n' + lines.join(',\n') + '\n' + indent + ']'
    }
    case 'string':
      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unreachable node kind ${node.kind}`)
  }
}

export function toJson(root) {
  return jsonValue(root, '') + '\n'
}

function typeOf(node) {
  if (node.kind === 'array') return 'array'
  return node.kind
}

function walkKeys(node, path, out) {
  out.push(`${path} ${typeOf(node)}`)
  if (node.kind === 'table') {
    for (const k of sortedKeys(node)) {
      walkKeys(node.map.get(k), path ? `${path}.${k}` : k, out)
    }
  } else if (node.kind === 'array') {
    node.items.forEach((it, i) => walkKeys(it, `${path}[${i}]`, out))
  }
}

export function toKeys(root) {
  const out = []
  for (const k of sortedKeys(root)) {
    walkKeys(root.map.get(k), k, out)
  }
  return out.length ? out.join('\n') + '\n' : ''
}
"}

